import {library,selectReference} from '../reference-model.js';
import {referenceHref} from '../navigation-model.js';
import {referenceArticle} from './reference-reader.js';
import {matchingPanel} from './owned.js';
import {esc,codeBadge,countLabel,seasonLabel,actionText,uiNames} from './shared.js';
import {dataStatus} from './data-status.js';

export function referenceLibrary({formulaRoute:r,studyFormula,items=[],seasonBackgroundOpen={},catalogStatus='ready'}){
  if(r.error)return `<div class="intro"><div><h1>This inspiration link doesn’t work</h1><p>The link may be out of date. Your saved outfits are unchanged.</p></div></div><section class="data-recovery" role="alert"><p>${esc(r.error)}</p><a class="btn" href="#formulas/library">${actionText('Back to inspiration','arrow-left')}</a></section>`;
  const season=library.seasons.find(s=>s.id===r.section);
  const entries=library.formulas.flatMap(formula=>formula.styles.map(style=>({formula,style})));
  const visible=entries.filter(e=>!season||e.style.seasons[0]===season.id);
  const current=studyFormula;
  return `<div class="formula-library reference-library"><div class="fl-heading"><div><span class="eyebrow">IDEAS TO TRY</span>${current?codeBadge(current.studyStyle):''}<h1>${current?esc(current.studyStyle.name):uiNames.formulas}</h1><p>Find a look you like, then explore options from your wardrobe. These images are inspiration, not photos of your clothes.</p></div></div>
    <nav class="collection-seasons" aria-label="Browse inspiration by season"><a href="#formulas/library" ${!season?'aria-current="page"':''}>All<span>${entries.length}</span></a>${library.seasons.map(s=>`<a href="#formulas/${s.id}" ${s.id===season?.id?'aria-current="page"':''}>${seasonLabel(s.id,s.name)}<span>${entries.filter(e=>e.style.seasons[0]===s.id).length}</span></a>`).join('')}</nav>
    ${r.notice?`<p class="note-block">${esc(r.notice)}</p>`:''}
    ${current?`<div class="reference-back"><a class="text-button" href="#formulas/${r.section}">${actionText('Back to '+(season?seasonLabel(season.id,season.name).toLowerCase()+' inspiration':'all inspiration'),'arrow-left')}</a><button type="button" class="btn" data-scroll-matches>${actionText('See options from my wardrobe','chevron-down')}</button></div>${referenceArticle(current)}${catalogStatus==='ready'?matchingPanel(items,current):`<section id="owned-matches" tabindex="-1">${dataStatus('catalog','Wardrobe items',catalogStatus)}</section>`}`:
    `${season?background(season,visible,seasonBackgroundOpen[season.id]):''}<div class="reference-count"><h2>${season?seasonLabel(season.id,season.name)+' inspiration':'All looks'} <small>${countLabel(visible.length,'look')}</small></h2><p>Open a look to explore its colors, styling tips and wardrobe matches.</p></div><div class="collection-grid">${visible.map(({formula,style})=>{const selected=selectReference(formula,{style:style.id});return `<article class="collection-card" data-reference-card="${style.id}"><a class="collection-image" href="${referenceHref(formula,style)}"><img src="${selected.variant.src}" alt="${esc(style.name)}, AI style idea" loading="lazy" width="825" height="1100"><span>AI inspiration · Not your wardrobe</span></a><div class="collection-card-body"><a class="code-link" href="${referenceHref(formula,style)}" aria-label="Explore look ${esc(style.code||style.id)}">${codeBadge(style)}</a><h2><a href="${referenceHref(formula,style)}">${esc(style.name)}</a></h2><p>${seasonLabel(style.seasons[0])} · ${countLabel(style.variants.length,'color option')}</p><a class="text-button" href="${referenceHref(formula,style)}" aria-label="Explore look: ${esc(style.name)}">${actionText('Explore look')}</a></div></article>`;}).join('')}</div>${!visible.length?'<section class="empty"><h2>No inspiration saved here yet</h2><p>You can still build outfits from the clothes in your wardrobe.</p><a class="btn" href="#closet">Browse my wardrobe</a></section>':''}`}
    <div class="fl-foot"><button type="button" class="text-button" data-formula-sources="true">${actionText('About the images and seasons','info')}</button><span>Suggestions aren’t a fit check.</span></div></div>`;
}
function background(season,entries,open){
  return `<details class="fl-season-background" data-season-background="${season.id}" ${open?'open':''}><summary><span>Seasonal ideas and styling tips</span><small>${countLabel(entries.length,'look')} · ${countLabel(season.principles.length,'tip')}</small></summary><section class="fl-recent"><h2>Looks for this season</h2><div class="fl-recent-strip">${entries.map(({formula,style})=>`<a href="${referenceHref(formula,style)}"><img src="${style.variants[0].src}" alt="" loading="lazy"><span>${esc(style.code)} · ${esc(style.name)}</span></a>`).join('')}</div></section><section class="fl-principles"><h2>Styling tips</h2><div class="fl-principle-grid">${season.principles.map(([title,text],i)=>`<details><summary><span>0${i+1}</span> ${esc(title)}</summary><p>${esc(text)}</p></details>`).join('')}</div></section></details>`;
}
